import{_ as d,o as e,c as o,a5 as r}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"소개","description":"","frontmatter":{"title":"소개","order":1},"headers":[],"relativePath":"ko/latest/web-tool/guide.md","filePath":"ko/latest/web-tool/guide.md","lastUpdated":1788455378000}'),a={name:"ko/latest/web-tool/guide.md"};function l(i,t,s,h,c,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="konado-webtool" tabindex="-1">Konado WebTool <a class="header-anchor" href="#konado-webtool" aria-label="Permalink to &quot;Konado WebTool&quot;">​</a></h1><h2 id="머리말" tabindex="-1">머리말 <a class="header-anchor" href="#머리말" aria-label="Permalink to &quot;머리말&quot;">​</a></h2><p>Konado WebTool은 Konado 프로젝트에 Web 플랫폼 개발 도구 지원을 제공하는 플러그인입니다. Godot 4.x는 Web 플랫폼에서 기본적으로 모든 키보드 단축키를 캡처하고 비활성화하므로 F12, F5 같은 브라우저 개발자 도구 단축키를 정상적으로 사용할 수 없습니다. 이 플러그인은 이 문제를 해결하여 Web 플랫폼에서 일반적인 브라우저 개발자 도구 단축키를 사용할 수 있게 하고, 개발자가 Web 환경에서 더 쉽게 디버깅하고 개발할 수 있도록 합니다.</p><h2 id="작동-원리" tabindex="-1">작동 원리 <a class="header-anchor" href="#작동-원리" aria-label="Permalink to &quot;작동 원리&quot;">​</a></h2><p>Konado WebTool은 Web 플랫폼에 JavaScript 코드를 주입해 단축키를 통과시키는 방식으로 동작합니다. 동작 과정은 다음과 같습니다.</p><ol><li>현재 플랫폼이 Web 플랫폼인지 확인합니다</li><li>Web 플랫폼이고 개발자 도구 지원이 활성화되어 있으면 단축키 처리 코드를 주입합니다</li><li>설정에 따라 허용할 단축키 목록을 동적으로 구성합니다</li><li>브라우저의 기본 동작은 유지하면서 허용된 단축키가 Godot으로 전파되지 않도록 합니다</li></ol><h3 id="다른-해결책과-비교" tabindex="-1">다른 해결책과 비교 <a class="header-anchor" href="#다른-해결책과-비교" aria-label="Permalink to &quot;다른 해결책과 비교&quot;">​</a></h3><table tabindex="0"><thead><tr><th>해결책</th><th>장점</th><th>단점</th></tr></thead><tbody><tr><td>Konado WebTool</td><td>사용하기 쉽고, 설정 가능성이 높으며, 유지보수가 좋음</td><td>뚜렷한 단점 없음</td></tr><tr><td>내보내기 템플릿 수동 수정</td><td>완전한 제어 가능</td><td>기술 요구가 높고 자주 업데이트해야 함</td></tr><tr><td>개발 환경 전환</td><td>데스크톱 플랫폼에서 디버깅 가능</td><td>Web 플랫폼 특유의 문제를 포착할 수 없음</td></tr></tbody></table><h2 id="지원되는-브라우저-단축키" tabindex="-1">지원되는 브라우저 단축키 <a class="header-anchor" href="#지원되는-브라우저-단축키" aria-label="Permalink to &quot;지원되는 브라우저 단축키&quot;">​</a></h2><p>이 단축키 규격은 Chrome, Firefox, Edge 등 주요 브라우저의 개발자 도구 표준 단축키를 기반으로 하며, 각 브라우저의 공식 문서를 참고했습니다.</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Tools/Keyboard_shortcuts" target="_blank" rel="noreferrer">Firefox DevTools</a></li><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/devtools-guide-chromium/shortcuts/" target="_blank" rel="noreferrer">Edge DevTools</a></li><li><a href="https://developer.chrome.com/docs/devtools/shortcuts/" target="_blank" rel="noreferrer">Chrome DevTools</a></li><li><a href="https://webkit.org/web-inspector/keyboard-shortcuts/" target="_blank" rel="noreferrer">Safari DevTools(WebKit)</a></li></ul><table tabindex="0"><thead><tr><th>단축키</th><th>기능</th><th>활성화 옵션</th></tr></thead><tbody><tr><td>F12</td><td>개발자 도구 열기</td><td><code>enable_f12</code></td></tr><tr><td>F5</td><td>페이지 새로고침</td><td><code>enable_f5</code></td></tr><tr><td>F11</td><td>전체 화면 전환</td><td><code>enable_f11</code></td></tr><tr><td>Ctrl+Shift+I (Win/Linux) / Cmd+Opt+I (Mac)</td><td>Elements 패널 열기</td><td><code>enable_ctrl_shift_i</code></td></tr><tr><td>Ctrl+Shift+J (Win/Linux) / Cmd+Opt+J (Mac)</td><td>Console 열기</td><td><code>enable_ctrl_shift_j</code></td></tr><tr><td>Ctrl+Shift+C (Win/Linux) / Cmd+Shift+C (Mac)</td><td>요소 검사 모드</td><td><code>enable_ctrl_shift_c</code></td></tr><tr><td>Ctrl+U (Win/Linux) / Cmd+U (Mac)</td><td>페이지 소스 보기</td><td><code>enable_ctrl_u</code></td></tr><tr><td>Ctrl+R (Win/Linux) / Cmd+R (Mac)</td><td>페이지 새로고침</td><td><code>enable_ctrl_r</code></td></tr></tbody></table><h2 id="설정-옵션" tabindex="-1">설정 옵션 <a class="header-anchor" href="#설정-옵션" aria-label="Permalink to &quot;설정 옵션&quot;">​</a></h2><p>자동 로드되는 <code>KonadoWebTool</code> 노드에서 다음 속성을 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>속성</th><th>유형</th><th>기본값</th><th>설명</th></tr></thead><tbody><tr><td><code>developer_shortcuts_enabled</code></td><td>bool</td><td>true</td><td>Web 개발자 도구 단축키 통과를 활성화할지 여부</td></tr><tr><td><code>allow_in_release</code></td><td>bool</td><td>false</td><td>릴리스 내보내기에서 단축키 통과를 활성화할지 여부</td></tr><tr><td><code>enable_f12</code></td><td>bool</td><td>true</td><td>F12 단축키를 활성화할지 여부</td></tr><tr><td><code>enable_f5</code></td><td>bool</td><td>true</td><td>F5 단축키를 활성화할지 여부</td></tr><tr><td><code>enable_f11</code></td><td>bool</td><td>true</td><td>F11 단축키를 활성화할지 여부</td></tr><tr><td><code>enable_ctrl_shift_i</code></td><td>bool</td><td>true</td><td>Ctrl+Shift+I 단축키를 활성화할지 여부</td></tr><tr><td><code>enable_ctrl_shift_j</code></td><td>bool</td><td>true</td><td>Ctrl+Shift+J 단축키를 활성화할지 여부</td></tr><tr><td><code>enable_ctrl_shift_c</code></td><td>bool</td><td>true</td><td>Ctrl+Shift+C 단축키를 활성화할지 여부</td></tr><tr><td><code>enable_ctrl_u</code></td><td>bool</td><td>true</td><td>Ctrl+U 단축키를 활성화할지 여부</td></tr><tr><td><code>enable_ctrl_r</code></td><td>bool</td><td>true</td><td>Ctrl+R 단축키를 활성화할지 여부</td></tr></tbody></table><p>프로덕션 환경에 디버깅 진입점이 노출되지 않도록 릴리스 내보내기에서는 기본적으로 단축키 처리기를 설치하지 않습니다. 런타임에 속성을 변경한 뒤 다음 호출로 설정을 적용합니다.</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoWebTool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refresh_shortcuts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>',17)])])}const p=d(a,[["render",l]]);export{_ as __pageData,p as default};
